// Translation dictionaries, keyed by the English string itself (same
// scheme as vfsoffice's inc/i18n.php: t('Some English text') looks
// itself up here, and a missing key/language always falls back to the
// English text passed in — never a blank string or broken key).
//
// Coverage today: all 6 languages (hi/te/ta/kn/ml alongside English)
// are fully populated for Header, Footer, each home-page section's
// heading/eyebrow/subtitle, and the SIP → Waiting → SWP calculator —
// the site's navigational chrome plus its most content-heavy tool.
// Verified programmatically: all 5 non-English dicts carry the exact
// same 155-key set, and all keys actually referenced via t() across
// components resolve in every language (see the check script used
// during development). Not yet covered: feature-card and testimonial
// body copy, FAQ answers, the compliance/regulatory disclosure text,
// and the Partner Hub / GST Helper / VFS Office Benefits pages —
// deliberately left in English for now, since getting financial and
// regulatory wording exactly right needs a professional review, not
// a single pass. Same "fails open" contract applies throughout.

