    'Instant account, no approval wait. Every new account gets 30 days of every feature unlocked, free.': 'तत्काल खाता, अनुमोदन प्रतीक्षा नहीं। हर नए खाते को 30 दिनों के लिए हर फीचर मुफ्त में अनलॉक मिलता है।',
    'Questions new users ask': 'नए उपयोगकर्ता जो प्रश्न पूछते हैं',
    "No jargon. Just what you'd actually want to know.": 'कोई शब्दजाल नहीं। बस वही जो आप वास्तव में जानना चाहेंगे।',
    "What happens when my 30-day trial ends?": 'जब मेरा 30-दिन का ट्रायल समाप्त हो जाता है तो क्या होता है?',
    "Nothing breaks and nothing is deleted. Your account simply drops back to the free Basic plan automatically — upgrade again whenever you're ready, at any time.": 'कुछ भी टूटता नहीं है और कुछ भी हटाया नहीं जाता है। आपका खाता स्वचालित रूप से मुफ्त Basic प्लान पर वापस आ जाता है — जब भी आप तैयार हों, किसी भी समय फिर से अपग्रेड करें।',
    "Is my commission data safe?": 'क्या मेरा कमीशन डेटा सुरक्षित है?',
    "PDF signing and Excel mapping happen entirely inside your own browser — those files are never uploaded to any server, even temporarily, during processing.": 'PDF हस्ताक्षर और Excel मैपिंग पूरी तरह से आपके अपने ब्राउज़र के अंदर होती है — वे फाइलें प्रोसेसिंग के दौरान किसी भी सर्वर पर कभी अपलोड नहीं की जातीं, यहां तक कि अस्थायी रूप से भी नहीं।',
    "Do I need to know Excel or GST rules?": 'क्या मुझे Excel या GST नियम जानने की आवश्यकता है?',
    "No. The GST & Commission Invoicing workflow is a guided, numbered checklist — it tells you what to do at each step, not the other way around.": 'नहीं। GST और कमीशन इनवॉइसिंग वर्कफ़्लो एक निर्देशित, क्रमांकित चेकलिस्ट है — यह आपको हर चरण में क्या करना है यह बताता है, इसके विपरीत नहीं।',
    "Can I change plans later?": 'क्या मैं बाद में प्लान बदल सकता हूं?',
    "Yes, any time, from your own account — upgrade, downgrade, or cancel. There's no separate request or approval needed.": 'हां, किसी भी समय, अपने खाते से — अपग्रेड, डाउनग्रेड, या रद्द करें। किसी अलग अनुरोध या अनुमोदन की आवश्यकता नहीं है।',
    "How do I pay?": 'मैं भुगतान कैसे करूं?',
    "By UPI (scan and enter your reference number) or by card/netbanking where available. A free plan needs no payment step at all.": 'UPI द्वारा (स्कैन करें और अपना संदर्भ नंबर दर्ज करें) या कार्ड/नेटबैंकिंग द्वारा जहां उपलब्ध हो। एक मुफ्त प्लान को किसी भुगतान चरण की बिल्कुल भी आवश्यकता नहीं है।',
    "What if I get stuck?": 'यदि मैं फंस जाऊं तो क्या होगा?',
    "Built-in Search covers documentation and FAQs instantly, and every plan includes access to Support Tickets for anything Search can't answer.": 'अंतर्निहित खोज तुरंत दस्तावेज़ीकरण और FAQ को कवर करती है, और हर प्लान में उन चीज़ों के लिए सपोर्ट टिकट तक पहुंच शामिल है जिनका खोज उत्तर नहीं दे सकती।',

