    'NPS adds an extra tax deduction under Sec 80CCD(1B) up to ₹50,000 and builds a disciplined retirement corpus.': 'NPS धारा 80CCD(1B) के तहत ₹50,000 तक अतिरिक्त कर कटौती जोड़ता है और एक अनुशासित सेवानिवृत्ति फंड बनाता है।',
