    'Map current costs to future value, then back-calc SIP needed. Use equity for long horizon; debt for near-term.': 'वर्तमान लागत को भविष्य के मूल्य से जोड़ें, फिर आवश्यक SIP की गणना करें। लंबी अवधि के लिए इक्विटी; निकट अवधि के लिए डेट का उपयोग करें।',
    'Inflation-adjusted goal values': 'महंगाई-समायोजित लक्ष्य मूल्य',
    'Dedicated goal-based funds': 'समर्पित लक्ष्य-आधारित फंड',
    'Annual review & rebalancing': 'वार्षिक समीक्षा और पुनर्संतुलन',
    'Combine NPS + MF SIPs for growth, then shift to income strategies near retirement.': 'वृद्धि के लिए NPS + MF SIP को मिलाएं, फिर सेवानिवृत्ति के करीब आय रणनीतियों की ओर बढ़ें।',
