    'Unlock liquidity instantly by pledging your mutual fund investments without selling them.': 'अपने म्यूचुअल फंड निवेश को बेचे बिना गिरवी रखकर तुरंत तरलता अनलॉक करें।',
    'Lower Interest Rates': 'कम ब्याज दरें',
    'Quick & Hassle-Free Processing': 'त्वरित और परेशानी मुक्त प्रोसेसिंग',
    'No Impact on Investments': 'निवेश पर कोई प्रभाव नहीं',
    'Build a financial cushion for emergencies with liquid & arbitrage mutual funds that ensure quick access to your money.': 'लिक्विड और आर्बिट्राज म्यूचुअल फंड के साथ आपातकाल के लिए एक वित्तीय कुशन बनाएं जो आपके पैसे तक त्वरित पहुंच सुनिश्चित करता है।',
    'High Liquidity – withdraw anytime': 'उच्च तरलता – कभी भी निकालें',
    'Better returns than Savings Account': 'बचत खाते से बेहतर रिटर्न',
