    'Diversified Asset Allocation': 'विविधीकृत परिसंपत्ति आवंटन',
    'Invest across equity, debt, and gold for balanced returns with lower risk.': 'कम जोखिम के साथ संतुलित रिटर्न के लिए इक्विटी, डेट और सोने में निवेश करें।',
