    'A plan is only as strong as the paperwork behind it — Family Vault keeps every policy, investment, identity document, and nominee detail in one secure place, so your family can actually find and use them when it matters.': 'कोई भी योजना उतनी ही मजबूत होती है जितने मजबूत उसके दस्तावेज़ — फैमिली वॉल्ट हर पॉलिसी, निवेश, पहचान दस्तावेज़ और नॉमिनी विवरण को एक सुरक्षित जगह पर रखता है, ताकि ज़रूरत पड़ने पर आपका परिवार उन्हें आसानी से खोज और उपयोग कर सके।',
