    // Faq
    'Why start with protection first?': 'सुरक्षा से पहले क्यों शुरू करें?',
    'Insurance prevents a single event from derailing your goals. After a safety net is in place, you can invest aggressively for growth.': 'बीमा एक घटना को आपके लक्ष्यों को पटरी से उतारने से रोकता है। सुरक्षा जाल स्थापित होने के बाद, आप वृद्धि के लिए आक्रामक रूप से निवेश कर सकते हैं।',
    'How much term cover do I need?': 'मुझे कितना टर्म कवर चाहिए?',
    'A practical range is 10–15× annual income or a human-life-value method that covers liabilities + future goals.': 'एक व्यावहारिक सीमा 10-15× वार्षिक आय है या एक ह्यूमन-लाइफ-वैल्यू विधि जो देनदारियों + भविष्य के लक्ष्यों को कवर करती है।',
    'Are mutual fund returns guaranteed?': 'क्या म्यूचुअल फंड रिटर्न गारंटीशुदा हैं?',
    'No. They are market-linked. Use asset allocation and a long horizon to reduce risk, and review annually.': 'नहीं। वे बाजार से जुड़े हैं। जोखिम कम करने के लिए परिसंपत्ति आवंटन और लंबी अवधि का उपयोग करें, और सालाना समीक्षा करें।',
    'Is NPS better than mutual funds?': 'क्या NPS म्यूचुअल फंड से बेहतर है?',
    'They serve different purposes. NPS shines for tax + retirement discipline; MFs give more flexibility and liquidity.': 'वे अलग-अलग उद्देश्यों की पूर्ति करते हैं। NPS कर + सेवानिवृत्ति अनुशासन के लिए बेहतर है; MF अधिक लचीलापन और तरलता देते हैं।',

    'Frequently Asked ': 'अक्सर पूछे जाने वाले ',
    'Questions': 'प्रश्न',
    'Short answers to common doubts.': 'सामान्य शंकाओं के संक्षिप्त उत्तर।',

