    'KYC Validation': 'KYC सत्यापन',
    'Verify your PAN and check whether your KYC is valid.': 'अपना PAN सत्यापित करें और जांचें कि आपका KYC वैध है या नहीं।',
    'Validate KYC': 'KYC सत्यापित करें',
    'Do KYC': 'KYC करें',
    'Complete your Online KYC for first-time investments.': 'पहली बार निवेश के लिए अपनी ऑनलाइन KYC पूरी करें।',
    'Mandatory for investing in Mutual Funds.': 'म्यूचुअल फंड में निवेश के लिए अनिवार्य।',
