    'Failed to process Excel file.': 'Excel ఫైల్‌ను ప్రాసెస్ చేయడంలో విఫలమైంది.',
    'GST & PDF Helper': 'GST & PDF సహాయకుడు',
    'Automatically place signatures on CAMS and KFINTECH PDFs': 'CAMS మరియు KFINTECH PDFలపై స్వయంచాలకంగా సంతకాలు ఉంచండి',
    'Automatically places the signature based on the selected template layout.': 'ఎంచుకున్న టెంప్లేట్ లేఅవుట్ ఆధారంగా స్వయంచాలకంగా సంతకాన్ని ఉంచుతుంది.',
