    'Search': 'శోధన',
    'One box that searches the whole app at once. Type a question and get results from modules, documentation, workflows, AMCs, FAQs, and reports — instead of hunting through menus.': 'మొత్తం యాప్‌ను ఒకేసారి శోధించే ఒక బాక్స్. ఒక ప్రశ్నను టైప్ చేసి మాడ్యూల్‌లు, డాక్యుమెంటేషన్, వర్క్‌ఫ్లోలు, AMCలు, FAQలు మరియు రిపోర్ట్‌ల నుండి ఫలితాలను పొందండి — మెనూలలో వెతకడానికి బదులుగా.',
    'Works instantly, no setup, included on every plan': 'తక్షణమే పనిచేస్తుంది, సెటప్ లేదు, ప్రతి ప్రణాళికలో చేర్చబడింది',
    'Can optionally answer in natural language once AI is enabled': 'AI ప్రారంభించబడిన తర్వాత ఐచ్ఛికంగా సహజ భాషలో సమాధానం ఇవ్వగలదు',
    'Search everything...': 'ప్రతిదాన్ని శోధించండి...',
