    'Documentation': 'డాక్యుమెంటేషన్',
    'result': 'ఫలితం',
    'AMCs & FAQs': 'AMCలు & FAQలు',
    "Every AMC's login link and speciality, already looked up. A built-in, always-current directory of Indian AMCs with empanelment status and direct login links.": 'ప్రతి AMC యొక్క లాగిన్ లింక్ మరియు ప్రత్యేకత, ఇప్పటికే వెతకబడింది. ఎంపానెల్‌మెంట్ స్థితి మరియు ప్రత్యక్ష లాగిన్ లింక్‌లతో భారతీయ AMCల యొక్క అంతర్నిర్మిత, ఎల్లప్పుడూ-ప్రస్తుత డైరెక్టరీ.',
    'No more hunting across bookmarks for the right AMC login': 'సరైన AMC లాగిన్ కోసం బుక్‌మార్క్‌లలో వెతకడం ఇక అవసరం లేదు',
    'Includes which AMCs accept US/Canada-resident investors': 'US/కెనడా-నివాస పెట్టుబడిదారులను ఏ AMCలు అంగీకరిస్తాయో చేర్చబడింది',
