    'Start free. Upgrade only when you need to.': 'ఉచితంగా ప్రారంభించండి. మీకు అవసరమైనప్పుడు మాత్రమే అప్‌గ్రేడ్ చేయండి.',
    'Every plan includes the 30-day full-access trial first — this is what each one costs and unlocks after that.': 'ప్రతి ప్రణాళికలో మొదట 30-రోజుల పూర్తి-యాక్సెస్ ట్రయల్ ఉంటుంది — దాని తర్వాత ప్రతి ఒక్కటి ఖర్చు మరియు అన్‌లాక్ చేసేది ఇదే.',
