    'Core client tools (calculators, planner, eKYC)': 'ప్రధాన క్లయింట్ టూల్స్ (కాలిక్యులేటర్లు, ప్లానర్, eKYC)',
    'AMC directory & bank payment info': 'AMC డైరెక్టరీ & బ్యాంక్ చెల్లింపు సమాచారం',
