    'Diversification across asset classes': 'ఆస్తి తరగతుల్లో వైవిధ్యీకరణ',
    'Reduces overall portfolio volatility': 'మొత్తం పోర్ట్‌ఫోలియో అస్థిరతను తగ్గిస్తుంది',
    'Potential for stable, long-term growth': 'స్థిరమైన, దీర్ఘకాలిక వృద్ధికి సామర్థ్యం',
    'Family Records': 'కుటుంబ రికార్డులు',
    'A plan is only as strong as the paperwork behind it — Family Vault keeps every policy, investment, identity document, and nominee detail in one secure place, so your family can actually find and use them when it matters.': 'ఏ ప్రణాళికైనా దాని వెనుక ఉన్న పత్రాల అంత బలంగా ఉంటుంది — ఫ్యామిలీ వాల్ట్ ప్రతి పాలసీ, పెట్టుబడి, గుర్తింపు పత్రం, నామినీ వివరాలను ఒకే సురక్షిత స్థలంలో ఉంచుతుంది, అవసరమైనప్పుడు మీ కుటుంబం వాటిని సులభంగా కనుగొని వాడుకోగలిగేలా.',
    'Insurance, investments, assets & liabilities in one view': 'బీమా, పెట్టుబడులు, ఆస్తులు & అప్పులు ఒకే వీక్షణలో',
    'Nominee coverage tracked per policy, gaps flagged automatically': 'ప్రతి పాలసీకి నామినీ కవరేజ్ ట్రాక్, లోపాలు స్వయంచాలకంగా గుర్తింపు',
    'Encrypted storage for PAN, Aadhaar & other identity documents': 'PAN, ఆధార్ & ఇతర గుర్తింపు పత్రాల కోసం ఎన్‌క్రిప్టెడ్ నిల్వ',
