    'Feedback Dashboard': 'கருத்து டாஷ்போர்டு',
    'Mail Campaigns': 'அஞ்சல் பிரச்சாரங்கள்',
    'Error & Issue Monitor': 'பிழை & சிக்கல் கண்காணிப்பு',
    'Plans & Pricing': 'திட்டங்கள் & விலை',
    'Start free. Upgrade only when you need to.': 'இலவசமாகத் தொடங்குங்கள். உங்களுக்குத் தேவைப்படும்போது மட்டும் மேம்படுத்துங்கள்.',
    'Every plan includes the 30-day full-access trial first — this is what each one costs and unlocks after that.': 'ஒவ்வொரு திட்டத்திலும் முதலில் 30-நாள் முழு-அணுகல் சோதனை அடங்கும் — அதன் பிறகு ஒவ்வொன்றும் செலவாகும் மற்றும் திறக்கும் விவரம் இதுவே.',
