    'Pick what you need now — ': 'இப்போது உங்களுக்குத் தேவையானதைத் தேர்ந்தெடுக்கவும் — ',
    'add more as life evolves.': 'வாழ்க்கை மாறும்போது மேலும் சேர்க்கவும்.',
