    'This is an illustration based on assumed rates of return and inflation for planning purposes only. Actual mutual fund returns are market-linked and cannot be guaranteed or predicted.': 'இது திட்டமிடல் நோக்கங்களுக்காக மட்டுமே கருதப்பட்ட வருமான விகிதங்கள் மற்றும் பணவீக்கத்தை அடிப்படையாகக் கொண்ட ஒரு உதாரணம். உண்மையான மியூச்சுவல் ஃபண்ட் வருமானம் சந்தையுடன் இணைக்கப்பட்டவை மற்றும் உத்தரவாதம் அல்லது கணிக்க முடியாது.',

