    'Securing the foundation against life’s uncertainties.': 'வாழ்க்கையின் நிச்சயமற்ற தன்மைகளுக்கு எதிராக அடித்தளத்தைப் பாதுகாத்தல்.',
    'Term Insurance:': 'டெர்ம் இன்சூரன்ஸ்:',
    'Replace future income if you’re not around.': 'நீங்கள் இல்லாதபோது எதிர்கால வருமானத்தை ஈடுசெய்கிறது.',
    'Health Insurance:': 'சுகாதார காப்பீடு:',
    'Protect savings from medical inflation.': 'மருத்துவ பணவீக்கத்திலிருந்து சேமிப்பைப் பாதுகாக்கவும்.',
    'Emergency Fund:': 'அவசர நிதி:',
