    'Completed! Signed {count} PDF(s).': 'ಪೂರ್ಣಗೊಂಡಿದೆ! {count} PDF(ಗಳು) ಸಹಿ ಮಾಡಲಾಗಿದೆ.',
    'Error: ': 'ದೋಷ: ',
