    'No mapping was created. Please generate signed PDFs first.': 'ಯಾವುದೇ ಮ್ಯಾಪಿಂಗ್ ರಚಿಸಲಾಗಿಲ್ಲ. ಮೊದಲು ಸಹಿ ಮಾಡಿದ PDFಗಳನ್ನು ರಚಿಸಿ.',
    '{count} row(s) updated successfully.': '{count} ಸಾಲು(ಗಳು) ಯಶಸ್ವಿಯಾಗಿ ನವೀಕರಿಸಲಾಗಿದೆ.',
    'Failed to process Excel file.': 'Excel ಫೈಲ್ ಅನ್ನು ಪ್ರಕ್ರಿಯೆಗೊಳಿಸಲು ವಿಫಲವಾಗಿದೆ.',
    'GST & PDF Helper': 'GST & PDF ಸಹಾಯಕ',
    'Automatically place signatures on CAMS and KFINTECH PDFs': 'CAMS ಮತ್ತು KFINTECH PDFಗಳಲ್ಲಿ ಸ್ವಯಂಚಾಲಿತವಾಗಿ ಸಹಿಗಳನ್ನು ಇರಿಸಿ',
    'Automatically places the signature based on the selected template layout.': 'ಆಯ್ಕೆಮಾಡಿದ ಟೆಂಪ್ಲೇಟ್ ವಿನ್ಯಾಸದ ಆಧಾರದ ಮೇಲೆ ಸ್ವಯಂಚಾಲಿತವಾಗಿ ಸಹಿಯನ್ನು ಇರಿಸುತ್ತದೆ.',
    'Template Mode': 'ಟೆಂಪ್ಲೇಟ್ ಮೋಡ್',
    'Input Format': 'ಇನ್‌ಪುಟ್ ಫಾರ್ಮ್ಯಾಟ್',
