    // PartnerHub page
    'Partner ': 'ಪಾರ್ಟ್ನರ್ ',
    'Hub': 'ಹಬ್',
    'Access partner dashboards, distributor portals, and relationship-manager details for all your financial services.': 'ನಿಮ್ಮ ಎಲ್ಲಾ ಹಣಕಾಸು ಸೇವೆಗಳಿಗಾಗಿ ಪಾರ್ಟ್ನರ್ ಡ್ಯಾಶ್‌ಬೋರ್ಡ್‌ಗಳು, ಡಿಸ್ಟ್ರಿಬ್ಯೂಟರ್ ಪೋರ್ಟಲ್‌ಗಳು ಮತ್ತು ಸಂಬಂಧ-ವ್ಯವಸ್ಥಾಪಕ ವಿವರಗಳನ್ನು ಪ್ರವೇಶಿಸಿ.',
    'Hide RM Details': 'RM ವಿವರಗಳನ್ನು ಮರೆಮಾಡಿ',
    'Show RM Details': 'RM ವಿವರಗಳನ್ನು ತೋರಿಸಿ',
