    'Plans & Pricing': 'ಯೋಜನೆಗಳು & ಬೆಲೆ',
    'Start free. Upgrade only when you need to.': 'ಉಚಿತವಾಗಿ ಪ್ರಾರಂಭಿಸಿ. ನಿಮಗೆ ಅಗತ್ಯವಿದ್ದಾಗ ಮಾತ್ರ ಅಪ್‌ಗ್ರೇಡ್ ಮಾಡಿ.',
    'Every plan includes the 30-day full-access trial first — this is what each one costs and unlocks after that.': 'ಪ್ರತಿ ಯೋಜನೆಯಲ್ಲಿ ಮೊದಲು 30-ದಿನದ ಪೂರ್ಣ-ಪ್ರವೇಶ ಪ್ರಯೋಗ ಸೇರಿದೆ — ಅದರ ನಂತರ ಪ್ರತಿಯೊಂದೂ ವೆಚ್ಚವಾಗುವುದು ಮತ್ತು ಅನ್‌ಲಾಕ್ ಆಗುವುದು ಇದೇ.',
