    'Unlimited credits': 'ಅಪರಿಮಿತ ಕ್ರೆಡಿಟ್‌ಗಳು',
    'All 31 tools': 'ಎಲ್ಲಾ 31 ಪರಿಕರಗಳು',
    'My Business Profile included': 'ಮೈ ಬಿಸಿನೆಸ್ ಪ್ರೊಫೈಲ್ ಸೇರಿಸಲಾಗಿದೆ',
