    'Plans & Pricing': 'പ്ലാനുകളും വിലയും',
    'Start free. Upgrade only when you need to.': 'സൗജന്യമായി ആരംഭിക്കുക. നിങ്ങൾക്ക് ആവശ്യമുള്ളപ്പോൾ മാത്രം അപ്ഗ്രേഡ് ചെയ്യുക.',
    'Every plan includes the 30-day full-access trial first — this is what each one costs and unlocks after that.': 'ഓരോ പ്ലാനിലും ആദ്യം 30-ദിവസത്തെ പൂർണ്ണ-ആക്സസ് ട്രയൽ ഉൾപ്പെടുന്നു — അതിനുശേഷം ഓരോന്നും ചെലവാകുന്നതും അൺലോക്ക് ചെയ്യുന്നതും ഇതാണ്.',
